ader-border-333333, #817562); --darkreader-inline-border-left: var(--darkreader-border-333333, #817562);\" data-darkreader-inline-bgcolor=\"\" data-darkreader-inline-bgimage=\"\" data-darkreader-inline-border-top=\"\" data-darkreader-inline-border-right=\"\" data-darkreader-inline-border-bottom=\"\" data-darkreader-inline-border-left=\"\">\r\n                <div>\r\n                    <strong style=\"color: rgb(255, 255, 255); display: block; font-size: 16px; margin-bottom: 5px; --darkreader-inline-color: var(--darkreader-text-ffffff, #fffff4);\" data-darkreader-inline-color=\"\">Основной сет</strong>\r\n                    <small style=\"color: rgb(119, 119, 119); font-size: 13px; line-height: 1.4; --darkreader-inline-color: var(--darkreader-text-777777, #aea08b);\" data-darkreader-inline-color=\"\">Бонусы за 2 и 4 части комплекта...</small>\r\n                </div>\r\n            </div>\r\n            <div style=\"background: rgb(15, 15, 15); padding: 25px; border-radius: 15px; border: 1px solid rgb(26, 26, 26); display: flex; align-items: center; --darkreader-inline-bgcolor: var(--darkreader-background-0f0f0f, #000000); --darkreader-inline-bgimage: none; --darkreader-inline-border-top: var(--darkreader-border-1a1a1a, #8c7f6b); --darkreader-inline-border-right: var(--darkreader-border-1a1a1a, #8c7f6b); --darkreader-inline-border-bottom: var(--darkreader-border-1a1a1a, #8c7f6b); --darkreader-inline-border-left: var(--darkreader-border-1a1a1a, #8c7f6b);\" data-darkreader-inline-bgcolor=\"\" data-darkreader-inline-bgimage=\"\" data-darkreader-inline-border-top=\"\" data-darkreader-inline-border-right=\"\" data-darkreader-inline-border-bottom=\"\" data-darkreader-inline-border-left=\"\">\r\n                <img src=\"https://via.placeholder.com/100\" style=\"width: 80px; height: 80px; margin-right: 20px; border-radius: 10px; background: rgb(21, 21, 21); border: 1px solid rgb(51, 51, 51); object-fit: contain; --darkreader-inline-bgcolor: var(--darkreader-background-151515, #000000); --darkreader-inline-bgimage: none; --darkreader-inline-border-top: var(--darkreader-border-333333, #817562); --darkreader-inline-border-right: var(--darkreader-border-333333, #817562); --darkreader-inline-border-bottom: var(--darkreader-border-333333, #817562); --darkreader-inline-border-left: var(--darkreader-border-333333, #817562);\" data-darkreader-inline-bgcolor=\"\" data-darkreader-inline-bgimage=\"\" data-darkreader-inline-border-top=\"\" data-darkreader-inline-border-right=\"\" data-darkreader-inline-border-bottom=\"\" data-darkreader-inline-border-left=\"\">\r\n                <div>\r\n                    <strong style=\"color: rgb(255, 255, 255); display: block; font-size: 16px; margin-bottom: 5px; --darkreader-inline-color: var(--darkreader-text-ffffff, #fffff4);\" data-darkreader-inline-color=\"\">Вторичный сет</strong>\r\n                    <small style=\"color: rgb(119, 119, 119); font-size: 13px; line-height: 1.4; --darkreader-inline-color: var(--darkreader-text-777777, #aea08b);\" data-darkreader-inline-color=\"\">Альтернатива для других ситуаций...</small>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <h2 style=\"color: rgb(255, 255, 255); text-transform: uppercase; border-left: 4px solid rgb(255, 255, 255); padding-left: 15px; margin-bottom: 20px; font-weight: 900; --darkreader-inline-color: var(--darkreader-text-ffffff, #fffff4); --darkreader-inline-border-left: var(--darkreader-border-ffffff, #242626);\" data-darkreader-inline-color=\"\" data-darkreader-inline-border-left=\"\">Материалы (Full 60 Lvl)</h2>\r\n        <div class=\"materials-grid\" style=\"background: rgb(10, 10, 10); padding: 35px; border-radius: 15px; border: 1px solid rgb(26, 26, 26); display: grid; grid-template-columns: repeat(4, 1fr); gap: 25px; text-align: center; margin-bottom: 40px; --darkreader-inline-bgcolor: var(--darkreader-background-0a0a0a, #000000); --darkreader-inline-bgimage: none; --darkreader-inline-border-top: var(--darkreader-border-1a1a1a, #8c7f6b); --darkreader-inline-border-right: var(--darkreader-border-1a1a1a, #8c7f6b); --darkreader-inline-border-bottom: var(--darkreader-border-1a1a1a, #8c7f6b); --darkreader-inline-border-left: var(--darkreader-border-1a1a1a, #8c7f6b);\" data-darkreader-inline-bgcolor=\"\" data-darkreader-inline-bgimage=\"\" data-darkreader-inline-border-top=\"\" data-darkreader-inline-border-right=\"\" data-darkreader-inline-border-bottom=\"\" data-darkreader-inline-border-left=\"\">\r\n            <div style=\"display: flex; flex-direction: column; align-items: center;\">\r\n                <div style=\"width: 85px; height: 85px; background: rgb(21, 21, 21); border: 1px solid rgb(51, 51, 51); border-radius: 50%; display: flex; align-items: center; justify-content: center; margin-bottom: 12px; box-shadow: rgba(0, 0, 0, 0.3) 0px 4px 10px; --darkreader-inline-bgcolor: var(--darkreader-background-151515, #000000); --darkreader-inline-bgimage: none; --darkreader-inline-border-top: var(--darkreader-border-333333, #817562); --darkreader-inline-border-right: var(--darkreader-border-333333, #817562); --darkreader-inline-border-bottom: var(--darkreader-border-333333, #817562); --darkreader-inline-border-left: var(--darkreader-border-333333, #817562); --darkreader-inline-boxshadow: var(--darkreader-background-0000004d, rgba(0, 0, 0, 0.3)) 0px 4px 10px;\" data-darkreader-inline-bgcolor=\"\" data-darkreader-inline-bgimage=\"\" data-darkreader-inline-border-top=\"\" data-darkreader-inline-border-right=\"\" data-darkreader-inline-border-bottom=\"\" data-darkreader-inline-border-left=\"\" data-darkreader-inline-boxshadow=\"\">\r\n                    <img src=\"https://via.placeholder.com/50\" style=\"width: 50px;\">\r\n                </div>\r\n                <small style=\"color: rgb(102, 102, 102); font-size: 11px; text-transform: uppercase; font-weight: bold; letter-spacing: 1px; --darkreader-inline-color: var(--darkreader-text-666666, #bdaf9a);\" data-darkreader-inline-color=\"\">Чипы</small>\r\n                <strong style=\"color: rgb(255, 255, 255); font-size: 16px; margin-top: 5px; --darkreader-inline-color: var(--darkreader-text-ffffff, #fffff4);\" data-darkreader-inline-color=\"\">x30</strong>\r\n            </div>\r\n            <div style=\"display: flex; flex-direction: column; align-items: center;\">\r\n                <div style=\"width: 85px; height: 85px; background: rgb(21, 21, 21); border: 1px solid rgb(51, 51, 51); border-radius: 50%; display: flex; align-items: center; justify-content: center; margin-bottom: 12px; box-shadow: rgba(0, 0, 0, 0.3) 0px 4px 10px; --darkreader-inline-bgcolor: var(--darkreader-background-151515, #000000); --darkreader-inline-bgimage: none; --darkreader-inline-border-top: var(--darkreader-border-333333, #817562); --darkreader-inline-border-right: var(--darkreader-border-333333, #817562); --darkreader-inline-border-bottom: var(--darkreader-border-333333, #817562); --darkreader-inline-border-left: var(--darkreader-border-333333, #817562); --darkreader-inline-boxshadow: var(--darkreader-background-0000004d, rgba(0, 0, 0, 0.3)) 0px 4px 10px;\" data-darkreader-inline-bgcolor=\"\" data-darkreader-inline-bgimage=\"\" data-darkreader-inline-border-top=\"\" data-darkreader-inline-border-right=\"\" data-darkreader-inline-border-bottom=\"\" data-darkreader-inline-border-left=\"\" data-darkreader-inline-boxshadow=\"\">\r\n                    <img src=\"https://via.placeholder.com/50\" style=\"width: 50px;\">\r\n                </div>\r\n                <small style=\"color: rgb(102, 102, 102); font-size: 11px; text-transform: uppercase; font-weight: bold; letter-spacing: 1px; --darkreader-inline-color: var(--darkreader-text-666666, #bdaf9a);\" data-darkreader-inline-color=\"\">Босс</small>\r\n                <strong style=\"color: rgb(255, 255, 255); font-size: 16px; margin-top: 5px; --darkreader-inline-color: var(--darkreader-text-ffffff, #fffff4);\" data-darkreader-inline-color=\"\">x46</strong>\r\n            </div>\r\n            <div style=\"display: flex; flex-direction: column; align-items: center;\">\r\n                <div style=\"width: 85px; height: 85px; background: rgb(21, 21, 21); border: 1px solid rgb(51, 51, 51); border-radius: 50%; display: flex; align-items: center; justify-content: center; margin-bottom: 12px; box-shadow: rgba(0, 0, 0, 0.3) 0px 4px 10px; --darkreader-inline-bgcolor: var(--darkreader-background-151515, #000000); --darkreader-inline-bgimage: none; --darkreader-inline-border-top: var(--darkreader-border-333333, #817562); --darkreader-inline-border-right: var(--darkreader-border-333333, #817562); --darkreader-inline-border-bottom: var(--darkreader-border-333333, #817562); --darkreader-inline-border-left: var(--darkreader-border-333333, #817562); --darkreader-inline-boxshadow: var(--darkreader-background-0000004d, rgba(0, 0, 0, 0.3)) 0px 4px 10px;\" data-darkreader-inline-bgcolor=\"\" data-darkreader-inline-bgimage=\"\" data-darkreader-inline-border-top=\"\" data-darkreader-inline-border-right=\"\" data-darkreader-inline-border-bottom=\"\" data-darkreader-inline-border-left=\"\" data-darkreader-inline-boxshadow=\"\">\r\n                    <img src=\"https://via.placeholder.com/50\" style=\"width: 50px;\">\r\n                </div>\r\n                <small style=\"color: rgb(102, 102, 102); font-size: 11px; text-transform: uppercase; font-weight: bold; letter-spacing: 1px; --darkreader-inline-color: var(--darkreader-text-666666, #bdaf9a);\" data-darkreader-inline-color=\"\">Опыт</small>\r\n                <strong style=\"color: rgb(255, 255, 255); font-size: 16px; margin-top: 5px; --darkreader-inline-color: var(--darkreader-text-ffffff, #fffff4);\" data-darkreader-inline-color=\"\">x75</strong>\r\n            </div>\r\n            <div style=\"display: flex; flex-direction: column; align-items: center;\">\r\n                <div style=\"width: 85px; height: 85px; background: rgb(21, 21, 21); border: 1px solid rgb(51, 51, 51); border-radius: 50%; display: flex; align-items: center; justify-content: center; margin-bottom: 12px; box-shadow: rgba(0, 0, 0, 0.3) 0px 4px 10px; --darkreader-inline-bgcolor: var(--darkreader-background-151515, #000000); --darkreader-inline-bgimage: none; --darkreader-inline-border-top: var(--darkreader-border-333333, #817562); --darkreader-inline-border-right: var(--darkreader-border-333333, #817562); --darkreader-inline-border-bottom: var(--darkreader-border-333333, #817562); --darkreader-inline-border-left: var(--darkreader-border-333333, #817562); --darkreader-inline-boxshadow: var(--darkreader-background-0000004d, rgba(0, 0, 0, 0.3)) 0px 4px 10px;\" data-darkreader-inline-bgcolor=\"\" data-darkreader-inline-bgimage=\"\" data-darkreader-inline-border-top=\"\" data-darkreader-inline-border-right=\"\" data-darkreader-inline-border-bottom=\"\" data-darkreader-inline-border-left=\"\" data-darkreader-inline-boxshadow=\"\">\r\n                    <img src=\"https://via.placeholder.com/50\" style=\"width: 50px;\">\r\n                </div>\r\n                <small style=\"color: rgb(102, 102, 102); font-size: 11px; text-transform: uppercase; font-weight: bold; letter-spacing: 1px; --darkreader-inline-color: var(--darkreader-text-666666, #bdaf9a);\" data-darkreader-inline-color=\"\">Денни</small>\r\n                <strong style=\"color: rgb(255, 255, 255); font-size: 16px; margin-top: 5px; --darkreader-inline-color: var(--darkreader-text-ffffff, #fffff4);\" data-darkreader-inline-color=\"\">800k</strong>\r\n            </div>\r\n        </div>\r\n\r\n        <h2 style=\"color: rgb(255, 255, 255); text-transform: uppercase; border-left: 4px solid rgb(255, 255, 255); padding-left: 15px; margin-bottom: 20px; font-weight: 900; --darkreader-inline-color: var(--darkreader-text-ffffff, #fffff4); --darkreader-inline-border-left: var(--darkreader-border-ffffff, #242626);\" data-darkreader-inline-color=\"\" data-darkreader-inline-border-left=\"\">Советы по игре</h2>\r\n        <div style=\"background: rgb(13, 13, 13); padding: 30px; border-radius: 12px; border: 1px dotted rgb(255, 255, 255); color: rgb(170, 170, 170); line-height: 1.8; --darkreader-inline-bgcolor: var(--darkreader-background-0d0d0d, #000000); --darkreader-inline-bgimage: none; --darkreader-inline-border-top: var(--darkreader-border-ffffff, #242626); --darkreader-inline-border-right: var(--darkreader-border-ffffff, #242626); --darkreader-inline-border-bottom: var(--darkreader-border-ffffff, #242626); --darkreader-inline-border-left: var(--darkreader-border-ffffff, #242626); --darkreader-inline-color: var(--darkreader-text-aaaaaa, #cabea9);\" data-darkreader-inline-bgcolor=\"\" data-darkreader-inline-bgimage=\"\" data-darkreader-inline-border-top=\"\" data-darkreader-inline-border-right=\"\" data-darkreader-inline-border-bottom=\"\" data-darkreader-inline-border-left=\"\" data-darkreader-inline-color=\"\">\r\n            <ul style=\"margin: 0; padding-left: 25px;\">\r\n                <li style=\"margin-bottom: 12px;\">Основная стратегия боя...</li>\r\n                <li>Как эффективно использовать пассивные навыки...</li>\r\n            </ul>\r\n        </div>\r\n    ','Wuthering Waves','Гайды','https://i.pinimg.com/736x/f1/48/2b/f1482bd2503b499b962a9d3fdb05b303.jpg','2026-04-18 17:18:26'),
(17,'Цзинь Си',NULL,'\r\n        <div class=\"empty-area\"><img src=\"https://i.pinimg.com/736x/de/9f/db/de9fdb05b2be9389318f6a7b50947e28.jpg\" style=\"max-width:100%; border-radius:10px; margin:20px 0; display:block;\"></div>\r\n        <h3>Описание резонатора</h3>\r\n        <p>Цзиньси [Jinhsi] — глава магистрата Цзиньчжоу, всем сердцем преданная \r\nсвоим обязанностям. Девушка имеет связь со стражем Цзюэ, который \r\nпредстает в форме огромного дракона. Цзиньси ежедневно сталкивается с \r\nразнообразными трудностями, однако все равно стремится противостоять им и\r\n привести человечество к светлому будущему. В игре представлена в \r\nкачестве Спектро резонатора, владеющего широким клинком.</p>\r\n\r\n        <div class=\"empty-area\"></div>\r\n        <h3>Характеристики резонатора</h3>\r\n        <p>Приоритет: Крит. шанс -&gt; Крит. урон -&gt; АТК%</p>\r\n\r\n        <div class=\"empty-area\"></div>\r\n        <h3>Преимущества и недостатки резонатора</h3>\r\n        <div style=\"display: flex; gap: 20px;\">\r\n            <div class=\"pros-box\"><b style=\"color:#2ecc71;\">Преимущества:</b><ul><li>Сильный основной Спектро дамагер, идеально подходящий в отряд прокастеров, не находящихся долго на поле боя.</li><li>Наносит большое количество урона за короткое время, а также способна сама себя усиливать.</li><li>Имеет полезные резонансные цепи, каждая из которых влияет на урон персонажа.</li><li>Сборка Цзиньси довольно проста, поскольку нужно ориентироваться только на увеличение исходящего урона.</li><li>Благодаря Унисону не привязана к энергии концерта и может свободно переключаться на союзников после завершения ротации.</li></ul></div>\r\n            <div class=\"cons-box\"><b style=\"color:#e74c3c;\">Недостатки:</b><ul><li>Без второй резонансной цепи требуется предварительно настакать Накал с \r\nпомощью союзников, чтобы избежать потери урона от навыка «Озаряющее \r\nявление».</li><li>Из-за состояния полета уязвима и требует аккуратной игры. С одной \r\nстороны, ей легче избегать вражеских ударов благодаря этой стойке, чем \r\nперсонажам, которые передвигаются по земле. С другой, если этого делать \r\nне получается, она становится более уязвима, чем другие герои.</li><li>Зависима перехода из одного состояния в другое, что обусловлено точным \r\nвыполнением ротации, однако это не всегда возможно из-за непредвиденных \r\nситуаций на поле боя.</li><li>Относительно ограничена в выборе союзников, но эта ситуация должна \r\nисправиться в последующих обновлениях при появлении большего количества \r\nгероев.</li></ul></div>\r\n        </div>\r\n\r\n        <div class=\"empty-area\"><img src=\"https://i.pinimg.com/736x/ec/ed/06/eced066c9abdf755ba39f2235341a904.jpg\" style=\"max-width:100%; border-radius:10px; margin:20px 0; display:block;\"></div>\r\n        <h3>Лучшие билды на резонатора в ВуВе</h3>\r\n        <p>Цзиньси в WuWa является основным дамагером, играющим от Спектро урона\r\n навыка резонанса, который бывает четырех разных видов, зависящих от \r\nсостояния персонажа. Кроме того, способна переключаться на союзников \r\nпосле завершения ротации и не тратить энергию концерта, что позволяет \r\nсущественно сокращать время нахождения в бою.</p><p>Поскольку Цзиньси ­—\r\n мейн-ДД, при ее сборке стоит ориентироваться на максимально возможное \r\nувеличение ее урона. Девушка нуждается в Спектро уроне, критах и силе \r\nатаки. Также среди полезных характеристик есть увеличение урона навыка \r\nрезонанса и ульты. Несмотря на то, что Цзиньси стремится как можно чаще \r\nиспользовать ульту, нет необходимости специально искать Эхо на \r\nвосстановление энергии, достаточно набрать этой характеристики в доп. \r\nстатах.</p><p></p>\r\n\r\n        <div class=\"empty-area\"></div>\r\n        <h3>Лучшее оружие</h3>\r\n        <table id=\"weapon-table\">\r\n            <thead><tr><th>Оружие</th><th>Редкость</th><th>Эффект</th></tr></thead>\r\n            <tbody><tr>\r\n                <td><div class=\"icon-box\"><img src=\"https://wotpack.ru/wp-content/uploads/2024/06/Ages-of-Harvest-220x220.png\" alt=\"\" width=\"80\" height=\"80\" style=\"width: 100%; height: auto; display: block;\"></div><strong>Ages </strong><strong>of </strong><strong>Harvest<br></strong>Базовая атака: 47-587<br>Крит.шанс: 5.4-24.3%</td>\r\n                <td style=\"color:#f1c40f;\">⭐⭐⭐⭐⭐</td>\r\n                <td style=\"text-align:left;\">Дает <strong>12%-24%</strong> бонус всего элементального урона. За \r\nкаждую базовую атаку дает 1 Благословение Веков, суммирующееся до 4 раз и\r\n пропадающее после выхода из боя. Накопив 4 или более стаков, носитель \r\nоружия поглощает их и повышает урон навыка резонанса на <strong>48%-96%</strong> на 2.5 сек. Эффект срабатывает раз в 6 сек.</td>\r\n            </tr></tbody>\r\n        </table>\r\n\r\n        <div class=\"empty-area\"></div>\r\n        <h3>Лучшие Эхо</h3>\r\n        <table id=\"echo-table\">\r\n            <thead><tr><th>Соната (Set)</th><th>Рекомендуемые Эхо</th></tr></thead>\r\n            <tbody><tr>\r\n                <td><div class=\"icon-box\" style=\"width:30px; height:30px;\"><img src=\"https://wotpack.ru/wp-content/uploads/2024/05/set_5.png\" alt=\"\" width=\"60\" height=\"60\" style=\"width: 100%; height: auto; display: block;\"></div>Соната<br><strong>2 части:</strong> повышает Спектро урон на 10%.<br><strong>5 частей:</strong> после использования Интро скилла Спектро урон повышается на 30% на 15 сек.</td>\r\n                <td>\r\n                    <div style=\"background:#151515; padding:10px; border-radius:8px; display:flex; align-items:center; gap:15px; text-align:left;\">\r\n                        <div class=\"icon-box\" style=\"margin:0;\"><img src=\"https://wotpack.ru/wp-content/uploads/2024/06/Jue-220x220.png\" alt=\"\" width=\"75\" height=\"75\" style=\"width: 100%; height: auto; display: block;\"></div>\r\n                        <div><strong>Jué</strong><br>Кш/Ку</div>\r\n                    </div>\r\n                </td>\r\n            </tr></tbody>\r\n        </table>\r\n\r\n        <div class=\"empty-area\"></div>\r\n        <h3>Лучшие команды</h3>\r\n        <table id=\"team-table\">\r\n            <thead><tr><th>Мейн-ДД</th><th>Сап-ДД</th><th>Сап-ДД / Саппорт</th><th>Саппорт</th></tr></thead>\r\n            <tbody><tr>\r\n                <td><div class=\"icon-box\"><img src=\"https://wotpack.ru/wp-content/uploads/2024/06/Jinshi-220x220.png\" alt=\"\" width=\"100\" height=\"100\" style=\"width: 100%; height: auto; display: block;\"></div><b>Имя</b><br><small style=\"color:#888;\">Роль</small></td>\r\n                <td><div class=\"icon-box\"><img src=\"https://wotpack.ru/wp-content/uploads/2024/05/taoqi_card-1.png\" alt=\"\" width=\"100\" height=\"100\" style=\"width: 100%; height: auto; display: block;\"></div><b>Имя</b><br><small style=\"color:#888;\">Роль</small></td>\r\n                <td><div class=\"icon-box\"><img src=\"https://wotpack.ru/wp-content/uploads/2024/05/verina_card-1.png\" alt=\"\" width=\"100\" height=\"100\" style=\"width: 100%; height: auto; display: block;\"></div><b>Имя</b><br><small style=\"color:#888;\">Роль</small></td>\r\n                <td><div class=\"icon-box\"></div><b>Имя</b><br><small style=\"color:#888;\">Роль</small></td>\r\n            </tr></tbody>\r\n        </table>\r\n\r\n        <div class=\"empty-area\"><img src=\"https://i.pinimg.com/736x/15/06/3b/15063b64bd00b56aa962e70994265b61.jpg\" style=\"max-width:100%; border-radius:10px; margin:20px 0; display:block;\"></div>\r\n        <h3>Итог</h3>\r\n        <p>Цзиньси в Wuthering Waves является комфортным главным дамагером, \r\nспособным нанести огромное количество урона за короткое время. Ее \r\nротация занимает не слишком большое время, что позволяет ставить ее в \r\nотряды с двумя дамагерами. Кроме того, способность Унисон дает \r\nвозможность не заморачиваться по поводу энергии концерта и свободное \r\nпереключаться между членами отряда несколько раз, нанося урон и обновляя\r\n баффы.</p><p>Тем не менее персонаж является сильно зависимым от набора \r\nНакала, однако его накопление становится комфортным только с получением \r\nвторой резонансной цепи. Несмотря на то, что удары в состоянии \r\nВоплощения берут скейлы урона от Освобождения резонанса, они все еще \r\nсчитаются обычными атаками, что облегчает подбор оружия для героини и \r\nделает ее дружелюбной к новичкам.</p><p></p>\r\n        <div class=\"empty-area\"></div>\r\n    ','wuwa','БИЛД','https://i.pinimg.com/1200x/6a/37/49/6a3749e7357cf8163ac8e9eed8bc92f2.jpg','2026-04-24 18:43:41'),
(18,'Коломбина',NULL,'\r\n                    \r\n        <h3 class=\"wp-section-title\">Описание Персонажа</h3><div style=\"text-align: center; margin: 20px 0;\"><img src=\"https://i.pinimg.com/736x/71/ea/f6/71eaf61ba771f23d76b1b7b509ad2e11.jpg\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); outline: none; box-shadow: none;\"></div><p><br><br></p>\r\n        <p>Лунная дева Коломбина занимает позицию персонажа поддержки и работает \r\nкак карманный дамагер с усилениями. Помимо сильных баффов и наложения \r\nГидро статуса, она преобразовывает обычные реакции в соответствующие \r\nЛунные, адаптируясь под элементы союзников.</p>\r\n        \r\n        <h3 class=\"wp-section-title\">Преимущества и Недостатки</h3><div style=\"text-align: center; margin: 20px 0;\"><img src=\"https://i.pinimg.com/736x/73/4e/79/734e799b443a61388f72a3217a970eb6.jpg\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); outline: none; box-shadow: none;\"></div><p><br><br></p>\r\n        <div style=\"display: flex; gap: 20px; margin: 20px 0;\">\r\n            <div class=\"pros-box\">\r\n                <b>Преимущества:</b>\r\n                <ul style=\"margin: 10px 0; padding-left: 20px; color: #ddd; font-size: 14px;\">\r\n                    <li><strong>Лучший саб-дд и саппорт под реакции Нод-Края</strong>, включая \r\nЛунные Бутонизацию, Заряд и Кристалл. Герои из этого региона зависимы от\r\n комфортного Гидро компаньона поддержки, и она полностью закрывает их \r\nпотребность в нём.</li><li>Нуждается только в <strong>критах и HP.</strong> Если хочется удешевить сборку, можно остановиться на максимизации здоровья.</li><li><strong>Конвертирует обычные реакции в их нод-краевские аналоги</strong>, позволяя составлять уникальные команды из старых персонажей.</li><li><strong>Упрощает исследование мира</strong>, в первую очередь Нод-Края, \r\nблагодаря комфортному спринту. В регионе воров может воскрешать \r\nсоюзников и взаимодействовать с мелкими животными с силой куувяки.</li>\r\n                </ul>\r\n            </div>\r\n            <div class=\"cons-box\">\r\n                <b>Недостатки:</b>\r\n                <ul style=\"margin: 10px 0; padding-left: 20px; color: #ddd; font-size: 14px;\">\r\n                    <li><strong>Практически не взаимодействует с компаньонами из других регионов</strong>.\r\n Она дает им Гидро статус и конвертирует реакцию в новый тип, но не \r\nявляется востребованным саппортом. Дамагеры Пиро, Крио или Анемо стихий и\r\n вовсе не получат никакой пользы от ее баффов.</li><li>Играет на С0, но <strong>в полную силу раскрывается с наличием созвездий</strong>, особенно с первым и вторым. Они повышают удобство, существенно влияют на дамаг и выживаемость команды.</li><li><strong>Мало вариантов эффективного оружия.</strong> Ей нужны HP, криты и\r\n бонусы к дамагу от реакций региона воров, которые встречаются \r\nотносительно редко. Баффы элементального урона для нее практически \r\nбесполезны, так как Гидро она дамажит меньше, чем реакциями.</li>\r\n                </ul>\r\n            </div>\r\n        </div>\r\n\r\n        <h3 class=\"wp-section-title\">Приоритет прокачки Таланты</h3><div style=\"text-align: center; margin: 20px 0;\"><img src=\"https://i.pinimg.com/736x/4e/8e/8f/4e8e8fe389b0b168d2b57d144ecba74d.jpg\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); outline: none; box-shadow: none;\"></div><p><br><br></p>\r\n        <p>В какую очередь стоит вливать ресурсы для максимальной эффективности:</p><p></p><li data-rocket-lazy-bg-9d1c8d7c-81fd-407b-8294-809e34a403db=\"loaded\"><strong>Е-шку</strong> и <strong>ульту</strong>\r\n стоит прокачивать равномерно, но после 6 уровня отдавать больший \r\nприоритет навыку. Он дает существенное количество дамага и статуса, а от\r\n сверхспособности исходит только бафф.</li>\r\n<li data-rocket-lazy-bg-9d1c8d7c-81fd-407b-8294-809e34a403db=\"loaded\"><strong>Удары с руки</strong> в большинстве сборок не нужны. Прокачивать их стоит при игре Субреткой на позиции драйвера через заряженные удары.</li><br><p></p>\r\n        <p><b>Порядок прокачки:</b>&nbsp;Элементальный навык (Е) ≥ Взрыв стихии (Q) &gt; Обычные атаки (по необходимости)</p>\r\n\r\n        <h3 class=\"wp-section-title\">Лучшие Созвездия</h3><div style=\"text-align: center; margin: 20px 0;\"><img src=\"https://i.pinimg.com/736x/42/f0/a4/42f0a4f1e295acb6a319000f2deef462.jpg\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); outline: none; box-shadow: none;\"></div><p><br><br></p>\r\n        <p>Лучшие созвездия Коломбины — <strong>С1</strong>, <strong>С2</strong> и <strong>С6</strong>:</p>\r\n        <ul>\r\n            <li><strong>C1 :</strong>&nbsp;<strong>Д</strong>обавляет полезные баффы Гравитационному \r\nвозмущению, которые, помимо улучшения дамага Субретки, повлияют на весь \r\nотряд в зависимости от текущих союзников. Бонусы закрывают недостатки \r\nкоманд, например, нужду в ВЭ% у Кирилла, низкое сопротивление прерыванию\r\n Нефер или недостаток выживаемости у Цзы Бай. Возмущение будет возникать\r\n самостоятельно раз в 15 сек., позволяя уделять меньше внимания \r\nнакоплению стаков.</li>\r\n            <li><strong>C2:</strong>&nbsp;также влияет на Гравитационное возмущение, поскольку, во-первых, \r\nпозволяет чаще его вызывать из-за повышения скорости накопления стаков, \r\nа, во-вторых, дает дополнительные баффы за него. Усиления повышают \r\nнапрямую те статы, от которых зависят ЛЗ, ЛБ и ЛК, а для самой девушки \r\nдается довольно много нужного HP.&nbsp; Хотя усиления, на первый взгляд, \r\nнезначительные, в сумме конста добавляет ощутимое удобство.</li>\r\n            <li><strong>C6:</strong>&nbsp;дает 80% К/У элементам, взаимодействующим внутри ульты Субретки, что \r\nсущественно повышает дамаг, поскольку нод-краевские реакции также \r\nзависят от критов. Бонус складываться не может. Например, если в команде\r\n состоят одновременно Кирилл, Коломбина и Лаума, то за вызов ЛЗ и ЛБ по \r\n80% К/У получат Электро, Гидро и Дендро. Гидро элемент, даже если \r\nиспользовался дважды, не получит 160% К/У.</li>\r\n        </ul>\r\n\r\n        <h3 class=\"wp-section-title\">Лучшее снаряжение (Оружие)</h3>\r\n        <table class=\"wp-table-weapon\">\r\n            <thead>\r\n                <tr>\r\n                    <th style=\"width: 30%;\">Оружие</th>\r\n                    <th style=\"width: 70%;\">Эффект / Характеристики</th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n                <tr>\r\n                    <td class=\"wp-cell-center\">\r\n                        <div class=\"wp-item-icon-wrapper\"><div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2025/12/vyzov-noktyurna-203x220.png\" alt=\"\" width=\"69\" height=\"75\" style=\"width: 100%; height: auto; display: block; outline: none; box-shadow: none;\"></div></div>\r\n                        <div class=\"wp-item-name\">Вызов ноктюрна</div>\r\n                        <div class=\"wp-stars\">★★★★★</div>\r\n                        <div class=\"wp-item-sub\">Базовые параметры и мейн-стат</div>\r\n                    </td>\r\n                    <td class=\"wp-cell-effect\">\r\n                        <p>Повышает макс. HP на <strong>10%-18%</strong>. Когда носитель активирует Лунную реакцию или дамажит ею, восстанавливает <strong>14-18</strong> ед. энергии раз в 18 сек. и на 12 сек. дает следующие усиления:\r\n</p><ul><li data-rocket-lazy-bg-9d1c8d7c-81fd-407b-8294-809e34a403db=\"loaded\">Макс. HP повышается на <strong>14%-22%</strong>.</li><li data-rocket-lazy-bg-9d1c8d7c-81fd-407b-8294-809e34a403db=\"loaded\">К/У нод-краевских реакций повышается на <strong>60%-140%</strong>.</li></ul>\r\n<p>Эффект активируется даже из кармана.</p>\r\n                    </td>\r\n                </tr>\r\n            </tbody>\r\n        </table>\r\n\r\n        <h3 class=\"wp-section-title\">Лучшие Артефакты</h3>\r\n        <div class=\"wp-grid-echo\" style=\"margin: 15px 0;\">\r\n            <div class=\"wp-echo-card-left\">\r\n                <div class=\"wp-block-header-text\">Комплект</div>\r\n                <div class=\"wp-echo-meta\">\r\n                    <div class=\"wp-item-blank-icon circle\"><img src=\"https://wotpack.ru/wp-content/uploads/2025/12/rassvetnaya-pesn-zvezdy-i-luny-ikonka.png\" alt=\"\" width=\"75\" height=\"75\" style=\"width: 100%; height: auto; display: block; outline: none; box-shadow: none;\"></div>\r\n                    <div class=\"wp-item-name\">Рассветная песнь звезды и луны</div>\r\n                    <div class=\"wp-set-desc\">2 части: повышает МС на 80 ед.<br>4-5 частей: пока носитель находится не на поле боя, дамаг Лунных реакций \r\nувеличивается на 20%. Если активно Высшее сияние, урон дополнительно \r\nувеличивается еще на 40%. Пропадает через 3 сек. после выхода на поле \r\nбоя.</div>\r\n                </div>\r\n            </div>\r\n            <div class=\"wp-echo-card-right\">\r\n                <div class=\"wp-block-header-text\">Рекомендуемые основные статы</div>\r\n                <div class=\"wp-echo-pool\">\r\n                    <div class=\"wp-echo-item\">\r\n                        <div class=\"wp-item-blank-icon\"></div>\r\n                        <div class=\"wp-echo-info\">\r\n                            <div class=\"wp-item-name\">Приоритет суб-статов:</div>\r\n                            <div class=\"wp-echo-stats\">Крит. шанс -&gt; Крит. урон -&gt; ATK% -&gt; Восстановление</div>\r\n                        </div>\r\n                    </div>\r\n                    <ul class=\"wp-echo-stats-list\">\r\n                        <li><strong>Часы:</strong>&nbsp;ВЭ% / Ку&nbsp;/ Кш&nbsp;/ HP</li><li><strong>Кубок:</strong>&nbsp;ВЭ% / Ку&nbsp;/ Кш&nbsp;/ HP</li><li><strong>Шапка:</strong>&nbsp;HP% /&nbsp;ВЭ%&nbsp;/ Кш или Ку</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <h3 class=\"wp-section-title\">Лучшие отряды и команды</h3>\r\n        <table class=\"wp-table-team\">\r\n            <thead>\r\n                <tr>\r\n                    <th style=\"width: 50%;\">Компоновка группы</th>\r\n                    <th style=\"width: 50%;\">Описание синергии и тактика</th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n                <tr>\r\n                    <td>\r\n                        <div class=\"wp-team-slots\">\r\n                            <div class=\"wp-slot\">\r\n                                <span class=\"wp-slot-role main-dd\">Мейн-ДД</span>\r\n                                <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2025/09/nefer-ikonka.png\" alt=\"\" width=\"75\" height=\"84\" style=\"width: 100%; height: auto; display: block; outline: none; box-shadow: none;\"></div>Нефер</div>\r\n                            <div class=\"wp-slot\">\r\n                                <span class=\"wp-slot-role sub-dd\">Сап-ДД</span>\r\n                                <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2025/12/kolombina-220x220.png\" alt=\"\" width=\"75\" height=\"75\" style=\"width: 100%; height: auto; display: block; outline: none; box-shadow: none;\"></div><span class=\"wp-slot-name\">Коломбина</span></div>\r\n                            <div class=\"wp-slot\">\r\n                                <span class=\"wp-slot-role support\">Саппорт</span>\r\n                                <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2025/07/lauma-ikonka-e1758658666555.png\" alt=\"\" width=\"75\" height=\"75\" style=\"width: 100%; height: auto; display: block; outline: none; box-shadow: none;\"></div><span class=\"wp-slot-name\">Лаума</span></div>\r\n                        </div>\r\n                    </td>\r\n                    <td class=\"wp-cell-effect\">\r\n                        <p>Очередность прожатия кнопок (ротация), как комбинировать баффы и ультимейты для нанесения максимального урона...</p>\r\n                    </td>\r\n                </tr>\r\n            </tbody>\r\n        </table>\r\n\r\n        <h3 class=\"wp-section-title\">Как играть (Ротация)</h3>\r\n        <p><strong>Порядок действий:</strong> Е (элементальный навык) &gt; Q (взрыв\r\n стихии) &gt; переключитесь на саб-дд для прожатия способностей&nbsp; &gt; \r\nпроведите ротацию основного дамагера.</p>\r\n        <p><br></p>\r\n                    ','genshin','БИЛД','https://i.pinimg.com/736x/1c/a8/3e/1ca83e44a683959cdcc080e6cb87af24.jpg','2026-05-23 17:41:34'),
(19,'Цзы Бай',NULL,'\r\n                    \r\n        <h3 class=\"wp-section-title\">Описание Персонажа</h3><div style=\"text-align: center; margin: 20px 0;\"><img src=\"https://i.pinimg.com/736x/ff/aa/e6/ffaae63c9d10fd84dd63f384e25c1f45.jpg\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); outline: none; box-shadow: none;\"></div><p><br><br></p>\r\n        <p>Адепт Белая Лошадь Цзы Бай входит в число легендарных Гео дамагеров и реализует реакцию Лунный кристалл. Владея одноручным клинком, она играет через стойку, где её обычные удары обретают элементальную инфузию, а навык принимает иную форму и становится основным источником урона.</p>\r\n        \r\n        <h3 class=\"wp-section-title\">Преимущества и Недостатки</h3><div style=\"text-align: center; margin: 20px 0;\"><img src=\"https://i.pinimg.com/736x/9f/40/e5/9f40e50f6a48f2cf1f544ade5059096c.jpg\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); outline: none; box-shadow: none;\"></div><p><br><br></p>\r\n        <div style=\"display: flex; gap: 20px; margin: 20px 0;\" contenteditable=\"false\">\r\n            <div class=\"pros-box\" contenteditable=\"true\">\r\n                <b>Преимущества:</b>\r\n                <ul style=\"margin: 10px 0; padding-left: 20px; color: #ddd; font-size: 14px;\">\r\n                    <li><b>Простота сборки</b>. Героиня нуждается в большом количестве защиты и критах, и при этом ей почти не нужно искать ВЭ%. Нужда всего в двух характеристиках делает подбор артефактов намного проще.</li><li><b>Уникальная реакция</b>. Реализация Лунного кристалла помогает закрыть блоки по механикам и требования некоторых врагов, например, Повелителя морозной ночи или чудовищ Дикой охоты.</li><li><b>Удобная пассивка на ВЭ</b>. В ночное время восстанавливает себе часть энергии, находясь в «кармане». При путешествии по открытому миру способность позволит постоянно держать ульту на максимуме.</li>\r\n                </ul>\r\n            </div>\r\n            <div class=\"cons-box\" contenteditable=\"true\">\r\n                <b>Недостатки:</b>\r\n                <ul style=\"margin: 10px 0; padding-left: 20px; color: #ddd; font-size: 14px;\">\r\n                    <li><b>Небольшая вариативность команд</b>. Лунный кристалл активируется только в Гео и Гидро сочетании. Прочие комбинации не дают нужного эффекта, поэтому Адепт заперта в командах с этими элементами.</li><li><b>Не играет с популярными саппортами</b>. Как и другие мейн-дд Лунного знака, девушка полагается на урон самой реакции, а не дамаг собственных кнопок. Бонусы на элем. урон, заложенные в пассивных талантах Гидро Архонта Фурины, хозяйки чайного дома Е Лань и многих других «старых» спутников поддержки ей не нужны.</li><li><b>Дорогая экипировка</b>. Подавляющее большинство действительно подходящих клинков можно получить только из молитвы оружия или Боевого пропуска. Героиня имеет лишь один F2P вариант.</li>\r\n                </ul>\r\n            </div>\r\n        </div><h3 class=\"wp-section-title\">Приоритет прокачки Таланты</h3><div style=\"text-align: center; margin: 20px 0;\"><img src=\"https://i.pinimg.com/736x/26/f9/10/26f910b2453b6bdfe98a437249f3f369.jpg\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); outline: none; box-shadow: none;\"></div><p><br><br></p>В какую очередь стоит вливать ресурсы для максимальной эффективности:<br><b>Порядок прокачки:</b> Элементальный навык -&gt; Взрыв стихий&nbsp;-&gt;&nbsp;Обычная атака<h3 class=\"wp-section-title\">Лучшие Созвездия</h3>\r\n        <p>Лучшие созвездия Цзы Бай — <b>С1, С2</b> и <b>С6</b>:</p>\r\n        <ul>\r\n            <li><b>C1:</b>&nbsp;Ускоряет набор очков, необходимых для активации заряженной Е-шки, и повышает количество возможных активаций для неё. Это «чистая» прибавка к урону исключительно самого Адепта, без изменения геймплейных особенностей и прибавок союзникам.</li>\r\n            <li><b>C2:</b>&nbsp;Наиболее выгодна в группах с Коломбиной, у которой есть собственный высокий урон, поскольку эффект распространяется не только на саму Цзы Бай, но и ее союзников.</li>\r\n            <li><b>C6:</b>&nbsp;Ещё больше ускоряет набор стаков и увеличивает урон ключевой реакции за превышенный лимит.</li>\r\n        </ul>\r\n\r\n        <h3 class=\"wp-section-title\">Лучшее снаряжение (Оружие)</h3>\r\n        <div class=\"wp-table-wrapper\" contenteditable=\"false\">\r\n            <table class=\"wp-table-weapon\">\r\n                <thead>\r\n                    <tr>\r\n                        <th style=\"width: 30%;\">Оружие</th>\r\n                        <th style=\"width: 70%;\">Эффект / Характеристики</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    <tr>\r\n                        <td class=\"wp-cell-center\">\r\n                            <div class=\"wp-item-icon-wrapper\"><div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2025/12/signa-tszy-bay-220x220.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div></div>\r\n                            <div class=\"wp-item-name\" contenteditable=\"true\">Светоносный осколок луны</div>\r\n                            <div class=\"wp-stars\" contenteditable=\"true\">★★★★★</div>\r\n                            <div class=\"wp-item-sub\" contenteditable=\"true\">Базовые параметры и мейн-стат</div>\r\n                        </td>\r\n                        <td class=\"wp-cell-effect\" contenteditable=\"true\">\r\n                            <p>Повышает защиту на <strong>20/25/30/35/40%</strong>. На 5 сек. после того как носитель использует навык, урон реакции Лунный кристалл увеличивается на <strong>64/80/96/112/128%</strong></p>\r\n                        </td>\r\n                    </tr>\r\n                <tr>\r\n        <td class=\"wp-cell-center\">\r\n            <div class=\"wp-item-icon-wrapper\"><div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2024/02/uraku-misugiri-1.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div></div>\r\n            <div class=\"wp-item-name\" contenteditable=\"true\">Ураку мисугири</div>\r\n            <div class=\"wp-stars\" contenteditable=\"true\">★★★★★</div>\r\n            <div class=\"wp-item-sub\" contenteditable=\"true\">Базовые параметры</div>\r\n        </td>\r\n        <td class=\"wp-cell-effect\" contenteditable=\"true\">\r\n            <p>Дамаг обычной атаки увеличивается на <strong>16/20/24/28/32%</strong>, а навыка — на <strong>24/30/36/42/48%</strong>.\r\n После того как активный герой поблизости наносит Гео урон, эти эффекты \r\nдополнительно увеличиваются на 100% на 15 сек. Кроме того, защита \r\nэкипированного персонажа повышается на <strong>20/25/30/35/40%</strong>.</p>\r\n        </td>\r\n    </tr><tr>\r\n        <td class=\"wp-cell-center\">\r\n            <div class=\"wp-item-icon-wrapper\"><div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2024/05/svet-listvennogo-razreza-182x220.webp\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div></div>\r\n            <div class=\"wp-item-name\" contenteditable=\"true\">Свет лиственного разреза</div>\r\n            <div class=\"wp-stars\" contenteditable=\"true\">★★★★★</div>\r\n            <div class=\"wp-item-sub\" contenteditable=\"true\">Базовые параметры</div>\r\n        </td>\r\n        <td class=\"wp-cell-effect\" contenteditable=\"true\">\r\n            <p>Крит. шанс увеличивается на <strong>4/5/6/7/8%</strong>. Когда обычная атака наносит элем. урон, она даёт эффект Лиственного выреза: дамаг атак с руки и навыков повышается на <strong>120/150/180/210/240%</strong> от мастерства стихий. После 28 активаций или через 12 сек. эффект снимается. Его можно получить не чаще одного раза в 12 сек.</p>\r\n        </td>\r\n    </tr><tr>\r\n        <td class=\"wp-cell-center\">\r\n            <div class=\"wp-item-icon-wrapper\"><div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2024/09/pesn-patrulya-pikov-171x220.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div></div>\r\n            <div class=\"wp-item-name\" contenteditable=\"true\">Песнь патруля пиков</div>\r\n            <div class=\"wp-stars\" contenteditable=\"true\">★★★★★</div>\r\n            <div class=\"wp-item-sub\" contenteditable=\"true\">Базовые параметры</div>\r\n        </td>\r\n        <td class=\"wp-cell-effect\" contenteditable=\"true\">\r\n            <p>Удар по противнику обычной атакой или атакой в падении дает эффект Оды цветам: защита повышается на&nbsp;<strong>8%-16%</strong>, а элементальный урон увеличивается на&nbsp;<strong>10%-20%</strong>.\r\n Эффект может возникнуть раз в 0.1 сек., длится 6 сек. и складывается до\r\n 2 раз. При получении или обновлении второго стака бонус элементального \r\nурона союзников повышается на&nbsp;<strong>8%-16%</strong>&nbsp;за каждую 1000 ед. защиты носителя на 15 сек. Максимальный бафф не может превышать&nbsp;<strong>25.6%-51.2%</strong>.</p>\r\n        </td>\r\n    </tr></tbody>\r\n            </table>\r\n            \r\n        </div>\r\n\r\n        <h3 class=\"wp-section-title\">Лучшие Артефакты</h3>\r\n        <div class=\"wp-artifacts-container\" contenteditable=\"false\">\r\n            <div class=\"wp-artifacts-list-wrapper\">\r\n                <div class=\"wp-grid-echo\">\r\n                    <div class=\"wp-echo-card-left\">\r\n                        <div class=\"wp-block-header-text\">Комплект</div>\r\n                        <div class=\"wp-echo-meta\">\r\n                            <div class=\"wp-item-blank-icon circle\"><img src=\"https://wotpack.ru/wp-content/uploads/2025/09/noch-otkrytiya-neba-220x220.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n                            <div class=\"wp-item-name\" contenteditable=\"true\">Ночь открытия неба</div>\r\n                            <div class=\"wp-set-desc\" contenteditable=\"true\">2 части: +80 ед. к мастерству стихий.<br>4-5 частей: Если персонажи команды поблизости активируют Лунные реакции, когда \r\nобладатель набора активен, на 4 сек. появляется эффект Сияющей луны: \r\nНамерение: если Лунное знамение отряда – Зарождающееся сияние/Высшее \r\nсияние, шанс крит. попадания увеличивается на 1<strong>5%/30</strong>%. \r\nЗа каждый активный эффект Сияющей луны разных видов в отряде, урон \r\nЛунных реакций всех персонажей отряда увеличивается на 10%. Эффекты \r\nСияющей луны не складываются.</div>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"wp-echo-card-right\">\r\n                        <div class=\"wp-block-header-text\">Рекомендуемые основные статы</div>\r\n                        <div class=\"wp-echo-pool\">\r\n                            <div class=\"wp-echo-item\">\r\n                                \r\n                                <div class=\"wp-echo-info\">\r\n                                    <div class=\"wp-item-name\" contenteditable=\"true\">Приоритет суб-статов:</div>\r\n                                    <div class=\"wp-echo-stats\" contenteditable=\"true\">Крит. шанс -&gt; Крит. урон -&gt; ATK% -&gt; Восстановление</div>\r\n                                </div>\r\n                            </div>\r\n                            <ul class=\"wp-echo-stats-list\" contenteditable=\"true\">\r\n                                <li><strong>Часы:</strong> ATK% / Мастерство стихий</li><li><strong>Кубок:</strong> Элементальный урон</li><li><strong>Шапка:</strong> Крит. шанс / Крит. урон</li>\r\n                            </ul>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            <div class=\"wp-grid-echo\" style=\"margin: 20px 0px 0px;\">\r\n        <div class=\"wp-echo-card-left\">\r\n            <div class=\"wp-block-header-text\">Комплект</div>\r\n            <div class=\"wp-echo-meta\">\r\n                <div class=\"wp-item-blank-icon circle\"><img src=\"https://wotpack.ru/wp-content/uploads/2023/08/kokon-sladkih-grez.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n                <div class=\"wp-item-name\" contenteditable=\"true\">Кокон сладких грёз</div>\r\n                <div class=\"wp-set-desc\" contenteditable=\"true\">2 части: + 30% к защите.<br>4-5 частей: Обладатель наделяется эффектом Любопытства после попадания по врагу Гео \r\nатакой раз в 0,3 сек. или раз в 3 сек., когда герой находится в \r\n«кармане». Эффект складывается до 4 ур. Каждый дает +6% к защите и +6% к\r\n Гео. Если герой не получает эффект в течение 6 сек., то он теряет 1 \r\nнакопленный уровень Любопытства.</div>\r\n            </div>\r\n        </div>\r\n        <div class=\"wp-echo-card-right\">\r\n            <div class=\"wp-block-header-text\">Рекомендуемые основные статы</div>\r\n            <div class=\"wp-echo-pool\">\r\n                <div class=\"wp-echo-item\">\r\n                    \r\n                    <div class=\"wp-echo-info\">\r\n                        <div class=\"wp-item-name\" contenteditable=\"true\">Приоритет суб-статов:</div>\r\n                        <div class=\"wp-echo-stats\" contenteditable=\"true\">Крит. шанс -&gt; Крит. урон -&gt; ATK%</div>\r\n                    </div>\r\n                </div>\r\n                <ul class=\"wp-echo-stats-list\" contenteditable=\"true\">\r\n                    <li><strong>Часы:</strong> ATK% / МС</li><li><strong>Кубок:</strong> Элем. урон</li><li><strong>Шапка:</strong> Крит. шанс / урон</li>\r\n                </ul>\r\n            </div>\r\n        </div>\r\n    </div><div class=\"wp-grid-echo\" style=\"margin: 20px 0px 0px;\">\r\n        <div class=\"wp-echo-card-left\">\r\n            <div class=\"wp-block-header-text\">Комплект</div>\r\n            <div class=\"wp-echo-meta\">\r\n                <div class=\"wp-item-blank-icon circle\"><img src=\"https://wotpack.ru/wp-content/uploads/2023/08/Ohotnik-Sumerechnogo-dvora-PNG.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n                <div class=\"wp-item-name\" contenteditable=\"true\">Охотник Сумеречного двора</div>\r\n                <div class=\"wp-set-desc\" contenteditable=\"true\">2 части: + 15% к урону обычной и заряженной атаки.<br>4-5 частей: Повышает шанс крит. попадания на 12% на 5 сек., когда текущее HP \r\nувеличивается или снижается. Эффект может складываться до 3 раз.</div>\r\n            </div>\r\n        </div>\r\n        <div class=\"wp-echo-card-right\">\r\n            <div class=\"wp-block-header-text\">Рекомендуемые основные статы</div>\r\n            <div class=\"wp-echo-pool\">\r\n                <div class=\"wp-echo-item\">\r\n                    \r\n                    <div class=\"wp-echo-info\">\r\n                        <div class=\"wp-item-name\" contenteditable=\"true\">Приоритет суб-статов:</div>\r\n                        <div class=\"wp-echo-stats\" contenteditable=\"true\">Крит. шанс -&gt; Крит. урон -&gt; ATK%</div>\r\n                    </div>\r\n                </div>\r\n                <ul class=\"wp-echo-stats-list\" contenteditable=\"true\">\r\n                    <li><strong>Часы:</strong> ATK% / МС</li><li><strong>Кубок:</strong> Элем. урон</li><li><strong>Шапка:</strong> Крит. шанс / урон</li>\r\n                </ul>\r\n            </div>\r\n        </div>\r\n    </div></div>\r\n            \r\n        </div>\r\n\r\n        <h3 class=\"wp-section-title\">Лучшие отряды и команды</h3><div style=\"text-align: center; margin: 20px 0;\"><img src=\"https://i.pinimg.com/736x/d6/f6/e0/d6f6e0d1ad70eabc2e1e724ebd008b32.jpg\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); outline: none; box-shadow: none;\"></div><p><br><br></p>\r\n        <div class=\"wp-table-wrapper\" contenteditable=\"false\">\r\n            <table class=\"wp-table-team\">\r\n                <thead>\r\n                    <tr>\r\n                        <th style=\"width: 55%;\">Компоновка группы</th>\r\n                        <th style=\"width: 45%;\">Описание синергии и тактика</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    <tr>\r\n                        <td>\r\n                            <div class=\"wp-team-slots\">\r\n                                \r\n        <div class=\"wp-slot\">\r\n            <span class=\"wp-slot-role main-dd\">Мейн-ДД</span>\r\n            <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2025/12/tszy-bay-220x220.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n            <span class=\"wp-slot-name\">Персонаж 1</span>\r\n        </div>\r\n        <div class=\"wp-slot\">\r\n            <span class=\"wp-slot-role sub-dd\">Сап-ДД</span>\r\n            <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2025/12/kolombina-220x220.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n            <span class=\"wp-slot-name\">Персонаж 2</span>\r\n        </div>\r\n        <div class=\"wp-slot\">\r\n            <span class=\"wp-slot-role support\">Саппорт</span>\r\n            <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2025/12/illugi-220x220.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n            <span class=\"wp-slot-name\">Персонаж 3</span>\r\n        </div>\r\n    \r\n        <div class=\"wp-slot\">\r\n            <span class=\"wp-slot-role support\">Саппорт/Хил</span>\r\n            <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2022/02/Zhongli-1-e1760863910828.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n            <span class=\"wp-slot-name\">Персонаж 4</span>\r\n        </div>\r\n                            </div>\r\n                        </td>\r\n                        <td class=\"wp-cell-effect\" contenteditable=\"true\">\r\n                            <p>Очередность прожатия кнопок (ротация), как комбинировать баффы и ультимейты для нанесения максимального урона...</p>\r\n                        </td>\r\n                    </tr>\r\n                <tr>\r\n        <td>\r\n            <div class=\"wp-team-slots\">\r\n                \r\n        <div class=\"wp-slot\">\r\n            <span class=\"wp-slot-role main-dd\">Мейн-ДД</span>\r\n            <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2025/12/tszy-bay-220x220.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n            <span class=\"wp-slot-name\" contenteditable=\"true\">Персонаж 1</span>\r\n        </div>\r\n        <div class=\"wp-slot\">\r\n            <span class=\"wp-slot-role sub-dd\">Сап-ДД</span>\r\n            <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2025/12/kolombina-220x220.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n            <span class=\"wp-slot-name\" contenteditable=\"true\">Персонаж 2</span>\r\n        </div>\r\n        <div class=\"wp-slot\">\r\n            <span class=\"wp-slot-role support\">Саппорт</span>\r\n            <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2023/04/e-lan.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n            <span class=\"wp-slot-name\" contenteditable=\"true\">Персонаж 3</span>\r\n        </div>\r\n    \r\n        <div class=\"wp-slot\">\r\n            <span class=\"wp-slot-role support\">Саппорт/Хил</span>\r\n            <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2022/02/Zhongli-1-e1760863910828.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n            <span class=\"wp-slot-name\" contenteditable=\"true\">Персонаж 4</span>\r\n        </div>\r\n            </div>\r\n        </td>\r\n        <td class=\"wp-cell-effect\" contenteditable=\"true\">\r\n            <p>Описание тактики новой альтернативной команды, её синергии и преимуществ...</p>\r\n        </td>\r\n    </tr><tr>\r\n        <td>\r\n            <div class=\"wp-team-slots\">\r\n                \r\n        <div class=\"wp-slot\">\r\n            <span class=\"wp-slot-role main-dd\">Мейн-ДД</span>\r\n            <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2025/12/tszy-bay-220x220.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n            <span class=\"wp-slot-name\" contenteditable=\"true\">Персонаж 1</span>\r\n        </div>\r\n        <div class=\"wp-slot\">\r\n            <span class=\"wp-slot-role sub-dd\">Сап-ДД</span>\r\n            <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2025/12/kolombina-220x220.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n            <span class=\"wp-slot-name\" contenteditable=\"true\">Персонаж 2</span>\r\n        </div>\r\n        <div class=\"wp-slot\">\r\n            <span class=\"wp-slot-role support\">Саппорт</span>\r\n            <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2023/02/albedo.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n            <span class=\"wp-slot-name\" contenteditable=\"true\">Персонаж 3</span>\r\n        </div>\r\n    \r\n        <div class=\"wp-slot\">\r\n            <span class=\"wp-slot-role support\">Саппорт/Хил</span>\r\n            <div class=\"wp-item-blank-icon\"><img src=\"https://wotpack.ru/wp-content/uploads/2022/02/Zhongli-1-e1760863910828.png\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); display: block; margin: 5px auto; outline: none; box-shadow: none;\"></div>\r\n            <span class=\"wp-slot-name\" contenteditable=\"true\">Персонаж 4</span>\r\n        </div>\r\n            </div>\r\n        </td>\r\n        <td class=\"wp-cell-effect\" contenteditable=\"true\">\r\n            <p>Описание тактики новой альтернативной команды, её синергии и преимуществ...</p>\r\n        </td>\r\n    </tr></tbody>\r\n            </table>\r\n            \r\n        </div>\r\n\r\n        <h3 class=\"wp-section-title\">Как играть (Ротация)</h3><div style=\"text-align: center; margin: 20px 0;\"><img src=\"https://i.pinimg.com/736x/bf/47/dd/bf47ddd4df0702181f55925b86956015.jpg\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid rgb(26, 26, 26); outline: none; box-shadow: none;\"></div><p><br><br></p>\r\n        <p>Способности Цзы Бай реализуются только на поле боя, поэтому она не может занимать роль «карманного» персонажа или саппорта, и плохо играет в полноценном револьвере из-за механики стойки. Пока девушка находится в отряде, создаваемые союзниками Гидро кристаллы преобразуются в Лунный кристалл, за счёт которых вокруг врага создаются три тотема в форме полумесяца, которые бьют его раз в определённое время.<br><br>Сдавая Е-шку, Адепт конвертирует урон обычных атак в Гео. Её навык преобразуется в усиленную форму и активируется после траты части собранных стаков, которые копит с начала стойки.<br><br>В таком состоянии ротация героини состоит из четырёх последовательных движений. Срывать анимации не рекомендуется, поскольку последний удар при полном Лунном резонансе наносит дополнительный Гео урон, считающийся дамагом Лунного кристалла. Чтобы поставленные конструкции внесли свою часть дамага, необходимо трижды попасть по противнику именно реакцией.</p>                ','genshin','БИЛД','https://i.pinimg.com/736x/cd/8a/68/cd8a680f17bc1eebe246cf5d99edc79f.jpg','2026-06-06 11:30:14'),
(22,'Чжун Ли',NULL,'\r\n        <h3 class=\"wp-section-title\">Описание Персонажа</h3><div style=\"text-align: center; margin: 20px 0;\"><img src=\"https://i.pinimg.com/736x/52/1d/9b/521d9b2d1d2fdaaab4f2993f50e63dc7.jpg\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid #1a1a1a; cursor: pointer;\"></div><p><br><br></p>\r\n        <p>Чжун Ли является одним из самых популярных персонажей Геншин Импакт, \r\nналичие которого в отряде обеспечивает прохождение любого контента в \r\nигре. Герой не только обладает самым крепким щитом, но также способен \r\nнаносить большой урон и раздавать полезные усиления с помощью \r\nсаппортских сетов артефактов. Кроме того, Чжун Ли весьма прост в сборке и\r\n использовании, из-за чего подойдет даже новичкам. Гео Архонт хорошо \r\nсебя показывает в любых командах, так как сочетается со многими \r\nперсонажами, и полезен при исследовании мира.</p>\r\n        \r\n        <h3 class=\"wp-section-title\">Преимущества и Недостатки</h3>\r\n        <div style=\"display: flex; gap: 20px; margin: 20px 0;\" contenteditable=\"false\">\r\n            <div class=\"pros-box\" contenteditable=\"true\">\r\n                <b>Преимущества:</b>\r\n                <ul style=\"margin: 10px 0; padding-left: 20px; color: #ddd; font-size: 14px;\">\r\n                    <li>Самый крепкий щит в игре и полноценная замена хилера в команде.</li><li>Снижение всех типов сопротивлений при активном щите на 20%, что значительно увеличивает дамаг отряда.</li><li>Хороший урон и контроль противников в большом радиусе от взрыва стихий.</li><li>Не привередлив к оружию, для него на любом аккаунте найдется достойное копье.</li><li>Значительно упрощает и ускоряет фарм руды.</li>\r\n                </ul>\r\n            </div>\r\n            <div class=\"cons-box\" contenteditable=\"true\">\r\n                <b>Недостатки:</b>\r\n                <ul style=\"margin: 10px 0; padding-left: 20px; color: #ddd; font-size: 14px;\">\r\n                    <li>В игре есть мобы, которые способны атаковать и отнимать здоровье даже у \r\nперсонажей, защищенных щитом. Против них эффективность Чжун Ли \r\nзначительно снижается.</li><li>Периодический Гео урон от колонны может мешать проведению элементальных реакций или разбивать лед на замороженных противниках.</li><li>Слишком долгая анимация взрыва стихий в некоторых командах снизит общий дамаг.</li><li>Иногда активный персонаж может залезть на колонну во время боя.</li>\r\n                </ul>\r\n            </div>\r\n        </div>\r\n\r\n        <h3 class=\"wp-section-title\">Приоритет прокачки Таланты</h3><div style=\"text-align: center; margin: 20px 0;\"><img src=\"https://i.pinimg.com/736x/d6/fb/e8/d6fbe8f638b37828a83acc149e84258c.jpg\" style=\"max-width: 100%; height: auto; border-radius: 8px; border: 1px solid #1a1a1a; cursor: pointer;\"></div><p><br><br></p>\r\n        <p>В какую очередь стоит вливать ресурсы для максимальной эффективности:</p>\r\n        <p><b>Порядок прокачки:</b> Обычная атака -&gt; Элементальный навык -&gt; Взрыв стихий</p>\r\n\r\n        <h3 class=\"wp-section-title\">Лучшие Созвездия</h3>\r\n        <p>Описание самых полезных созвездий/эффектов при получении копий:</p>\r\n        <ul>\r\n            <li><strong>C1&nbsp;</strong>Дает Чжун Ли возможность создавать на поле сразу две Каменные стелы. Это позволит более удобно использовать сет Стойкость Миллелита.</li>\r\n            <li><strong>C2 </strong>важно для саб-дд билда, в котором постоянно задействуется ульта. Активация щита после взрыва стихий позволит экономить время в сражении, что особенно актуально в Бездне.</li>\r\n            <li><strong>C4&nbsp;</strong>направлено на увеличение радиуса ульты Чжун Ли, благодаря чему получится\r\n цеплять большее количество противников. Кроме того, увеличивается \r\nдлительность Окаменение, что полезно для контроля врагов.</li>\r\n        </ul>\r\n\r\n        <h3 class=\"wp-section-title\">Лучшее снаряжение (Оружие)</h3>\r\n        <div class=\"wp-table-wrapper\" contenteditable=\"false\">\r\n            <table class=\"wp-table-weapon\">\r\n                <thead>\r\n                    <tr>\r\n                        <th style=\"width: 30%;\">Оружие</th>\r\n                        <th style=\"width: 70%;\">Эффект / Характеристики</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    <tr>\r\n                        <td class=\"wp-cell-center\">\r\n                            <div class=\"wp-item-icon-wrapper\"><div class=\"wp-item-blank-icon\"></div></div>\r\n                            <div class=\"wp-item-name\" contenteditable=\"true\">Название сигнатурки</div>\r\n                            <div class=\"wp-stars\" contenteditable=\"true\">★★★★★</div>\r\n                            <div class=\"wp-item-sub\" contenteditable=\"true\">Базовые параметры и мейн-стат</div>\r\n                        </td>\r\n                        <td class=\"wp-cell-effect\" contenteditable=\"true\">\r\n                            <p>Описание пассивного бонуса, условий его срабатывания и синергии...</p>\r\n                        </td>\r\n                    </tr>\r\n                </tbody>\r\n            </table>\r\n            <button type=\"button\" class=\"wp-inline-add-btn\" onclick=\"addRowToWeapon(this)\" style=\"margin-top: 10px; width: 100%; padding: 10px; background: rgb(20, 20, 20); border: 1px solid rgb(51, 51, 51); font-weight: bold; cursor: pointer; border-radius: 6px; color: rgb(255, 77, 0);\">➕ ДОБАВИТЬ ВАРИАНТ ОРУЖИЯ</button>\r\n        </div>\r\n\r\n        <h3 class=\"wp-section-title\">Лучшие Артефакты</h3>\r\n        <div class=\"wp-artifacts-container\" contenteditable=\"false\">\r\n            <div class=\"wp-artifacts-list-wrapper\">\r\n                <div class=\"wp-grid-echo\">\r\n                    <div class=\"wp-echo-card-left\">\r\n                        <div class=\"wp-block-header-text\">Комплект</div>\r\n                        <div class=\"wp-echo-meta\">\r\n                            <div class=\"wp-item-blank-icon circle\"></div>\r\n                            <div class=\"wp-item-name\" contenteditable=\"true\">Название фулл-комплекта</div>\r\n                            <div class=\"wp-set-desc\" contenteditable=\"true\">2 части: Бонус характеристик<br>4-5 частей: Уникальный эффект сета при выполнении условий</div>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"wp-echo-card-right\">\r\n                        <div class=\"wp-block-header-text\">Рекомендации</div>\r\n                        <div class=\"wp-echo-recommend-title\" contenteditable=\"true\">Why choose this set?</div>\r\n                        <div class=\"wp-echo-recommend-text\" contenteditable=\"true\">\r\n                            <p>Опишите синергию комплекта с персонажем, почему эти бонусы эффективны и в каких ситуациях данный сет раскрывает себя лучше всего...</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            <button type=\"button\" class=\"wp-inline-add-btn\" onclick=\"addRowToArtifact(this)\" style=\"margin-top: 15px; width: 100%; padding: 10px; background: rgb(20, 20, 20); border: 1px dashed rgb(51, 51, 51); font-weight: bold; cursor: pointer; border-radius: 6px; color: rgb(255, 77, 0);\">➕ ДОБАВИТЬ ЕЩЕ СЕТ АРТЕФАКТОВ</button>\r\n        </div>\r\n\r\n        <h3 class=\"wp-section-title\">Лучшие отряды и команды</h3>\r\n        <div class=\"wp-table-wrapper\" contenteditable=\"false\">\r\n            <table class=\"wp-table-team\">\r\n                <thead>\r\n                    <tr>\r\n                        <th style=\"width: 55%;\">Компоновка группы</th>\r\n                        <th style=\"width: 45%;\">Описание синергии и тактика</th>\r\n                    </tr>\r\n                </thead>\r\n                <tbody>\r\n                    <tr>\r\n                        